import { zMongoId } from "@shared/application/dto/zod/validators/string/string.zod.validators";

import { isGameIdSetOnGameRole } from "@question/application/dto/zod/refinements/question-author/question-author.dto.zod.refinements";
import { QUESTION_AUTHOR_ROLES } from "@question/domain/constants/question.constants";

const QUESTION_AUTHOR_DTO = z.strictObject({
  role: z.enum(QUESTION_AUTHOR_ROLES)
    .describe("Question's author role")
    .meta({ example: QUESTION_AUTHOR_ROLES[0] }),
  gameId: zMongoId()
    .optional()
    .describe("Game's unique identifier, if the author is a game"),
  name: z.string()
    .optional()
    .describe("Question author's name, if applicable")
    .meta({ example: "TriviaMaster3000" }),
}).refine(isGameIdSetOnGameRole, { error: "Game ID must be set if and only if the author role is 'game'." })
  .describe("Question's author");

export type QuestionAuthorDto = z.infer<typeof QUESTION_AUTHOR_DTO>;

export { QUESTION_AUTHOR_DTO };

import { z } from "zod";

import { QUESTION_REJECTION_TYPES } from "@question/domain/constants/question.constants";

const QUESTION_REJECTION_DTO = z.strictObject({
  type: z.enum(QUESTION_REJECTION_TYPES)
    .describe("Question rejection's type")
    .meta({ example: QUESTION_REJECTION_TYPES[0] }),
  comment: z.string()
    .optional()
    .describe("Comment explaining the reason for rejection")
    .meta({ example: "The question is too ambiguous." }),
}).describe("Question rejection details");

export type QuestionRejectionDto = z.infer<typeof QUESTION_REJECTION_DTO>;

export { QUESTION_REJECTION_DTO };

