  zQuestionAnswer,
  zQuestionLocalizedAnswer,
  zQuestionContext,
  zQuestionLocalizedContext,
  zQuestionTrivia,
  zQuestionLocalizedTrivia,
};

import { z } from "zod";

import type { ZodBoolean } from "zod";

function zQuestionThemeAssignmentIsPrimary(): ZodBoolean {
  return z.boolean()
    .describe("Indicates if the assigned theme is the primary theme for the question");
}

function zQuestionThemeAssignmentIsHint(): ZodBoolean {
  return z.boolean()
    .describe("Indicates if the assigned theme is a hint for the question's answer");
}

export {
  zQuestionThemeAssignmentIsPrimary,
  zQuestionThemeAssignmentIsHint,
};

import { z } from "zod";

import { areValuesUniqueFromStrings } from "@shared/application/dto/zod/refinements/array/array.zod.refinements";
import { normalizeToArray } from "@shared/application/dto/zod/preprocessors/array/array.zod.preprocessors";
import { zCreateFilterArray } from "@shared/application/dto/zod/validators/array/array.zod.validators";
import { LOCALES } from "@shared/domain/value-objects/locale/locale.constants";
import { zIsoDateTime, zMongoId } from "@shared/application/dto/zod/validators/string/string.zod.validators";
import { zStringBoolean } from "@shared/application/dto/zod/validators/boolean/boolean.zod.validators";

import { QUESTION_AUTHOR_ROLES, QUESTION_CATEGORIES, QUESTION_SOURCE_URLS_MAX_ITEMS, QUESTION_SOURCE_URLS_MIN_ITEMS, QUESTION_STATUSES, QUESTION_COGNITIVE_DIFFICULTIES } from "@question/domain/constants/question.constants";
import { FIND_RANDOM_QUESTIONS_BODY_EXCLUDED_IDS_MAXIMUM, FIND_RANDOM_QUESTIONS_BODY_EXCLUDED_IDS_MINIMUM } from "@question/application/dto/find-random-questions-body/constants/find-random-questions-body.dto.constants";
import { QUESTION_IDS_FILTER_MAXIMUM, QUESTION_IDS_FILTER_MINIMUM } from "@question/application/dto/shared/constants/question-ids-filter-query.dto.constants";
import { QUESTION_IS_ADULT_CONTENT_FILTER_DESCRIPTION } from "@question/application/dto/zod/validators/question/constants/question-adult-content.dto.zod.validators.constants";
import type { QuestionAuthorRoleEnum, QuestionCategoryEnum, QuestionStatusEnum, QuestionCognitiveDifficultyEnum } from "@question/domain/types/question.value-objects";

import type { ZodEnum, ZodURL, ZodArray, ZodString, ZodISODateTime, ZodOptional, ZodPreprocess, ZodBoolean, ZodCodec } from "zod";

import type { LocaleEnum } from "@shared/domain/value-objects/locale/locale.types";

function zQuestionAuthorRole(): ZodEnum<QuestionAuthorRoleEnum> {
  return z.enum(QUESTION_AUTHOR_ROLES)
    .describe("Question author's role");
}

function zQuestionCognitiveDifficulty(): ZodEnum<QuestionCognitiveDifficultyEnum> {
  return z.enum(QUESTION_COGNITIVE_DIFFICULTIES)
    .describe("Question's cognitive difficulty level");
}

function zQuestionStatus(): ZodEnum<QuestionStatusEnum> {
  return z.enum(QUESTION_STATUSES)
    .describe("Question's status");
}

function zQuestionCategory(): ZodEnum<QuestionCategoryEnum> {
  return z.enum(QUESTION_CATEGORIES)
    .describe("Question's category");
}

function zQuestionApplicableLocales(minItems = 1): ZodOptional<ZodArray<ZodEnum<LocaleEnum>>> {
  return z.array(z.enum(LOCALES))
    .min(minItems)
    .max(LOCALES.length)
    .refine(areValuesUniqueFromStrings, { message: "Locales must be unique" })
    .optional()
    .describe("Subset of locales this question is relevant for; omit if relevant for all locales");
}

function zQuestionSourceUrls(): ZodArray<ZodURL> {
  return z.array(z.url())
    .min(QUESTION_SOURCE_URLS_MIN_ITEMS)
    .max(QUESTION_SOURCE_URLS_MAX_ITEMS)
    .refine(areValuesUniqueFromStrings, { message: "Source URLs must be unique" })
    .describe("List of unique source URLs for the question")
    .meta({ example: ["https://example.com/source1", "https://example.com/source2"] });
}

function zQuestionExcludedIdsFilter(): ZodOptional<ZodPreprocess<ZodArray<ZodString>>> {
  return zCreateFilterArray(
    zMongoId().describe("Question ID to exclude"),
    "Excluded IDs must be unique",
    "List of question IDs to exclude from the random pool",
    FIND_RANDOM_QUESTIONS_BODY_EXCLUDED_IDS_MINIMUM,
    FIND_RANDOM_QUESTIONS_BODY_EXCLUDED_IDS_MAXIMUM,
  );
}

function zQuestionCategoriesFilter(): ZodOptional<ZodPreprocess<ZodArray<ZodEnum<QuestionCategoryEnum>>>> {
  return zCreateFilterArray(
    z.enum(QUESTION_CATEGORIES),
    "Categories must be unique",
    "List of categories to include (OR logic)",
    1,
  );
}

function zQuestionCognitiveDifficultiesFilter(): ZodOptional<ZodPreprocess<ZodArray<ZodEnum<QuestionCognitiveDifficultyEnum>>>> {
  return zCreateFilterArray(
    z.enum(QUESTION_COGNITIVE_DIFFICULTIES),
    "Cognitive difficulties must be unique",
    "List of cognitive difficulties to include (OR logic)",
    1,
  );
}

function zQuestionThemeIdsFilter(): ZodOptional<ZodPreprocess<ZodArray<ZodString>>> {
  return z.preprocess(
    normalizeToArray,
    z.array(zMongoId().describe("Theme ID to filter questions by")).min(1),
  )
    .optional()
    .describe("List of theme IDs to filter questions by (OR logic)");
}

function zQuestionIdsFilter(): ZodOptional<ZodPreprocess<ZodArray<ZodString>>> {
  return z.preprocess(
    normalizeToArray,
    z.array(zMongoId().describe("Question ID to filter by"))
      .min(QUESTION_IDS_FILTER_MINIMUM)
      .max(QUESTION_IDS_FILTER_MAXIMUM)
      .refine(areValuesUniqueFromStrings, { message: "IDs must be unique" }),
  )
    .optional()
    .describe("List of question IDs to filter by (OR logic)");
}

function zQuestionIsAdultContentFilter(): ZodOptional<ZodCodec<ZodString, ZodBoolean>> {
  return zStringBoolean()
    .optional()
    .describe(QUESTION_IS_ADULT_CONTENT_FILTER_DESCRIPTION);
}

function zQuestionIsAdultContentBooleanFilter(): ZodOptional<ZodBoolean> {
  return z.boolean()
    .optional()
    .describe(QUESTION_IS_ADULT_CONTENT_FILTER_DESCRIPTION);
}

function zQuestionId(): ZodString {
  return zMongoId()
    .describe("Question's unique identifier");
}

function zQuestionCreatedAt(): ZodISODateTime {
  return zIsoDateTime()
    .describe("Question's creation date");
}

function zQuestionUpdatedAt(): ZodISODateTime {
  return zIsoDateTime()
    .describe("Question's last update date");
}

function zQuestionIsAdultContent(): ZodBoolean {
  return z.boolean()
    .describe("Whether the question contains adult content");
}

export {
  zQuestionAuthorRole,
  zQuestionCognitiveDifficulty,
  zQuestionStatus,
  zQuestionCategory,
  zQuestionApplicableLocales,
  zQuestionSourceUrls,
  zQuestionExcludedIdsFilter,
  zQuestionCategoriesFilter,
  zQuestionCognitiveDifficultiesFilter,
  zQuestionThemeIdsFilter,
  zQuestionIdsFilter,
  zQuestionIsAdultContentFilter,
  zQuestionIsAdultContentBooleanFilter,
  zQuestionId,
  zQuestionCreatedAt,
  zQuestionUpdatedAt,
  zQuestionIsAdultContent,
};

