        ...QUESTION_MONGOOSE_REPOSITORY_PIPELINE,
      ];

      await repositories.question.findRandom(options);

      expect(mocks.models.question.aggregate).toHaveBeenCalledExactlyOnceWith(expectedPipeline);
    });

    it("should add theme ids to match stage as ObjectId $in on nested themeId when provided.", async() => {
      const locale = LOCALES[0];
      const themeIds = ["618c1f4b3a2f000000000001", "618c1f4b3a2f000000000002"];
      const options = createFakeFindRandomQuestionsOptions({
        limit: 5,
        themeIds,
        excludedIds: undefined,
        categories: undefined,
        cognitiveDifficulties: undefined,
        isAdultContent: undefined,
        locale,
      });
      const expectedPipeline = [
        {
          $match: {
            "status": QUESTION_STATUS_ACTIVE,
            "themes.themeId": { $in: themeIds.map(id => new Types.ObjectId(id)) },
            "$or": [
              { applicableLocales: { $exists: false } },
              { applicableLocales: { $size: 0 } },
              { applicableLocales: locale },
            ],
            ...expectedLocaleCompletenessCondition(locale),
          },
        },
        { $sample: { size: 5 } },
        ...QUESTION_MONGOOSE_REPOSITORY_PIPELINE,
      ];

      await repositories.question.findRandom(options);

      expect(mocks.models.question.aggregate).toHaveBeenCalledExactlyOnceWith(expectedPipeline);
    });

    it("should compose all filters in a single match stage when all options are provided.", async() => {
      const locale = LOCALES[0];
      const excludedIds = ["618c1f4b3a2f000000000001"];
      const categories: QuestionCategory[] = ["trivia"];
      const cognitiveDifficulties: QuestionCognitiveDifficulty[] = ["easy"];
      const themeIds = ["618c1f4b3a2f000000000002"];
      const options = createFakeFindRandomQuestionsOptions({ limit: 5, excludedIds, categories, cognitiveDifficulties, themeIds, isAdultContent: undefined, locale });
      const expectedPipeline = [
        {
          $match: {
            "status": QUESTION_STATUS_ACTIVE,
            "_id": { $nin: excludedIds.map(id => new Types.ObjectId(id)) },
            "category": { $in: categories },
            "cognitiveDifficulty": { $in: cognitiveDifficulties },
            "themes.themeId": { $in: themeIds.map(id => new Types.ObjectId(id)) },
            "$or": [
              { applicableLocales: { $exists: false } },
              { applicableLocales: { $size: 0 } },
              { applicableLocales: locale },
            ],
            ...expectedLocaleCompletenessCondition(locale),
          },
        },
        { $sample: { size: 5 } },
        ...QUESTION_MONGOOSE_REPOSITORY_PIPELINE,
      ];

      await repositories.question.findRandom(options);

      expect(mocks.models.question.aggregate).toHaveBeenCalledExactlyOnceWith(expectedPipeline);
    });

    it("should not add filter to match stage when provided array is empty.", async() => {
      const locale = LOCALES[0];
      const options = createFakeFindRandomQuestionsOptions({
        limit: 5,
        excludedIds: [],
        categories: [],
        cognitiveDifficulties: [],
        themeIds: [],
        isAdultContent: undefined,
        locale,
      });
      const expectedPipeline = [
        {
          $match: {
            status: QUESTION_STATUS_ACTIVE,
            $or: [
              { applicableLocales: { $exists: false } },
              { applicableLocales: { $size: 0 } },
              { applicableLocales: locale },
            ],
            ...expectedLocaleCompletenessCondition(locale),
          },
        },
        { $sample: { size: 5 } },
        ...QUESTION_MONGOOSE_REPOSITORY_PIPELINE,
      ];

      await repositories.question.findRandom(options);

      expect(mocks.models.question.aggregate).toHaveBeenCalledExactlyOnceWith(expectedPipeline);
    });

    it("should map and return questions when called.", async() => {
      const options = createFakeFindRandomQuestionsOptions({
        limit: 3,
        excludedIds: undefined,
        categories: undefined,
        cognitiveDifficulties: undefined,
        themeIds: undefined,
        isAdultContent: undefined,
        locale: LOCALES[0],
      });
      const questionAggregates = [
        createFakeQuestionAggregate(),
        createFakeQuestionAggregate(),
      ];
      mocks.models.question.aggregate.mockResolvedValueOnce(questionAggregates);

      await repositories.question.findRandom(options);

      expect(mocks.mappers.question.createQuestionFromAggregate).toHaveBeenCalledTimes(questionAggregates.length);
    });

    it("should call the mapper with every aggregate returned from model when called.", async() => {
      const options = createFakeFindRandomQuestionsOptions({
        limit: 2,
        excludedIds: undefined,
        categories: undefined,
        cognitiveDifficulties: undefined,
        themeIds: undefined,
        isAdultContent: undefined,
        locale: LOCALES[0],
      });
      const questionAggregates = [
        createFakeQuestionAggregate(),
        createFakeQuestionAggregate(),
      ];
      mocks.models.question.aggregate.mockResolvedValueOnce(questionAggregates);

      await repositories.question.findRandom(options);

      expect(mocks.mappers.question.createQuestionFromAggregate).toHaveBeenNthCalledWith(1, questionAggregates[0], 0, questionAggregates);
      // Acceptable as testing multiple calls to the mapper function requires multiple expects in a single block
      // oxlint-disable-next-line max-expects
      expect(mocks.mappers.question.createQuestionFromAggregate).toHaveBeenNthCalledWith(2, questionAggregates[1], 1, questionAggregates);
    });

    it("should return mapped questions from model when called.", async() => {
      const options = createFakeFindRandomQuestionsOptions({
        limit: 2,
        excludedIds: undefined,
        categories: undefined,
        cognitiveDifficulties: undefined,
        themeIds: undefined,
        isAdultContent: undefined,
        locale: LOCALES[0],
      });
      const questionAggregates = [
        createFakeQuestionAggregate(),
        createFakeQuestionAggregate(),
      ];
      mocks.models.question.aggregate.mockResolvedValueOnce(questionAggregates);
      const expectedQuestions = [
        createFakeQuestion(),
        createFakeQuestion(),
      ];

      mocks.mappers.question.createQuestionFromAggregate
        .mockReturnValueOnce(expectedQuestions[0])
        .mockReturnValueOnce(expectedQuestions[1]);

      const actualQuestions = await repositories.question.findRandom(options);

      expect(actualQuestions).toStrictEqual(expectedQuestions);
    });

    it("should shuffle the mapped questions when called.", async() => {
      const options = createFakeFindRandomQuestionsOptions({
        limit: 2,
        excludedIds: undefined,
        categories: undefined,
        cognitiveDifficulties: undefined,
        themeIds: undefined,
        isAdultContent: undefined,
        locale: LOCALES[0],
      });
      const questionAggregates = [
        createFakeQuestionAggregate(),
        createFakeQuestionAggregate(),
      ];
      mocks.models.question.aggregate.mockResolvedValueOnce(questionAggregates);
      const mappedQuestions = [
        createFakeQuestion({ id: "618c1f4b3a2f0000000000a1" }),
        createFakeQuestion({ id: "618c1f4b3a2f0000000000a2" }),
      ];
      const shuffledQuestions = [
        createFakeQuestion({ id: "618c1f4b3a2f0000000000a3" }),
        createFakeQuestion({ id: "618c1f4b3a2f0000000000a4" }),
      ];

      mocks.mappers.question.createQuestionFromAggregate
        .mockReturnValueOnce(mappedQuestions[0])
        .mockReturnValueOnce(mappedQuestions[1]);
      vi.mocked(arrayHelpers.shuffleArray).mockReturnValueOnce(shuffledQuestions);

      const actualQuestions = await repositories.question.findRandom(options);

      expect(actualQuestions).toStrictEqual(shuffledQuestions);
    });

    it("should call shuffleArray with the mapped questions when called.", async() => {
      const options = createFakeFindRandomQuestionsOptions({
        limit: 2,
        excludedIds: undefined,
        categories: undefined,
        cognitiveDifficulties: undefined,
        themeIds: undefined,
        isAdultContent: undefined,
        locale: LOCALES[0],
      });
      const questionAggregates = [
        createFakeQuestionAggregate(),
        createFakeQuestionAggregate(),
      ];
      mocks.models.question.aggregate.mockResolvedValueOnce(questionAggregates);
      const mappedQuestions = [
        createFakeQuestion({ id: "618c1f4b3a2f0000000000b1" }),
        createFakeQuestion({ id: "618c1f4b3a2f0000000000b2" }),
      ];

      mocks.mappers.question.createQuestionFromAggregate
        .mockReturnValueOnce(mappedQuestions[0])
        .mockReturnValueOnce(mappedQuestions[1]);

      await repositories.question.findRandom(options);

      expect(vi.mocked(arrayHelpers.shuffleArray)).toHaveBeenCalledExactlyOnceWith(mappedQuestions);
    });
  });

  describe(QuestionMongooseRepository.prototype.countLiveByThemeId, () => {
    it("should return count of live questions when referencing a theme.", async() => {
      const themeId = "618c1f4b3a2f000000000038";
      const expectedCount = 2;
      mocks.models.question.countDocuments.mockResolvedValueOnce(expectedCount);

      const actual = await repositories.question.countLiveByThemeId(themeId);

      expect(actual).toBe(expectedCount);
    });

    it("should return 0 when no live questions reference the theme.", async() => {
      const themeId = "618c1f4b3a2f000000000039";
      mocks.models.question.countDocuments.mockResolvedValueOnce(0);

      const actual = await repositories.question.countLiveByThemeId(themeId);

      expect(actual).toBe(0);
    });

    it("should call countDocuments with correct query parameters when called.", async() => {
      const themeId = "618c1f4b3a2f00000000003a";
      mocks.models.question.countDocuments.mockResolvedValueOnce(0);

      await repositories.question.countLiveByThemeId(themeId);

      expect(mocks.models.question.countDocuments).toHaveBeenCalledExactlyOnceWith({
        themes: {
          $elemMatch: {
            themeId: new Types.ObjectId(themeId),
          },
        },
        status: {
          $in: [QUESTION_STATUS_PENDING, QUESTION_STATUS_ACTIVE],
        },
      });
    });
  });

  describe(QuestionMongooseRepository.prototype.getStats, () => {
    const facetResult: QuestionStatsAggregationResult = {
      totalStage: [{ count: 5 }],
      byStatusStage: [{ active: 3, pending: 2 }],
      byCategoryStage: [{ trivia: 5 }],
      byCognitiveDifficultyStage: [{ medium: 5 }],
      byAuthorRoleStage: [{ admin: 5 }],
      byRejectionTypeStage: [{ "duplicate-question": 1 }],
      fullyTranslatedCountStage: [{ count: 4 }],
      incompleteTranslationCountStage: [{ count: 1 }],
    };

    it("should call aggregate with the stats pipeline when invoked.", async() => {
      mocks.models.question.aggregate.mockResolvedValueOnce([facetResult as unknown as QuestionAggregate]);
      await repositories.question.getStats();

      expect(mocks.models.question.aggregate).toHaveBeenCalledExactlyOnceWith(QUESTION_STATS_MONGOOSE_REPOSITORY_PIPELINE);
    });

    it("should return total from the $facet result when called.", async() => {
      mocks.models.question.aggregate.mockResolvedValueOnce([facetResult as unknown as QuestionAggregate]);
      const result = await repositories.question.getStats();

      expect(result.total).toBe(5);
    });

    it("should return total as 0 when totalStage is empty.", async() => {
      mocks.models.question.aggregate.mockResolvedValueOnce([{ ...facetResult, totalStage: [] } as unknown as QuestionAggregate]);
      const result = await repositories.question.getStats();

      expect(result.total).toBe(0);
    });

    it("should return partial record for byStatus when aggregation rows are provided.", async() => {
      mocks.models.question.aggregate.mockResolvedValueOnce([facetResult as unknown as QuestionAggregate]);
      const result = await repositories.question.getStats();

      expect(result.byStatus).toStrictEqual({ active: 3, pending: 2 });
    });

    it("should return partial record for byCategory when aggregation rows are provided.", async() => {
      mocks.models.question.aggregate.mockResolvedValueOnce([facetResult as unknown as QuestionAggregate]);
      const result = await repositories.question.getStats();

      expect(result.byCategory).toStrictEqual({ trivia: 5 });
    });

    it("should return partial record for byCognitiveDifficulty when aggregation rows are provided.", async() => {
      mocks.models.question.aggregate.mockResolvedValueOnce([facetResult as unknown as QuestionAggregate]);
      const result = await repositories.question.getStats();

      expect(result.byCognitiveDifficulty).toStrictEqual({ medium: 5 });
    });

    it("should return partial record for byAuthorRole when aggregation rows are provided.", async() => {
      mocks.models.question.aggregate.mockResolvedValueOnce([facetResult as unknown as QuestionAggregate]);
      const result = await repositories.question.getStats();

      expect(result.byAuthorRole).toStrictEqual({ admin: 5 });
    });

    it("should return partial record for byRejectionType when aggregation rows are provided.", async() => {
      mocks.models.question.aggregate.mockResolvedValueOnce([facetResult as unknown as QuestionAggregate]);
      const result = await repositories.question.getStats();

      expect(result.byRejectionType).toStrictEqual({ "duplicate-question": 1 });
    });

    it("should populate non-zero status counts from the aggregation when called.", async() => {
      mocks.models.question.aggregate.mockResolvedValueOnce([facetResult as unknown as QuestionAggregate]);
      const result = await repositories.question.getStats();

      expect(result.byStatus.active).toBe(3);
    });

    it("should return empty record for byStatus when byStatusStage is empty.", async() => {
      mocks.models.question.aggregate.mockResolvedValueOnce([{ ...facetResult, byStatusStage: [] } as unknown as QuestionAggregate]);
      const result = await repositories.question.getStats();

      expect(result.byStatus).toStrictEqual({});
    });

    it("should return empty record for byCategory when byCategoryStage is empty.", async() => {
      mocks.models.question.aggregate.mockResolvedValueOnce([{ ...facetResult, byCategoryStage: [] } as unknown as QuestionAggregate]);
      const result = await repositories.question.getStats();

      expect(result.byCategory).toStrictEqual({});
    });

    it("should return empty record for byCognitiveDifficulty when byCognitiveDifficultyStage is empty.", async() => {
      mocks.models.question.aggregate.mockResolvedValueOnce([{ ...facetResult, byCognitiveDifficultyStage: [] } as unknown as QuestionAggregate]);
      const result = await repositories.question.getStats();

      expect(result.byCognitiveDifficulty).toStrictEqual({});
    });

    it("should return empty record for byAuthorRole when byAuthorRoleStage is empty.", async() => {
      mocks.models.question.aggregate.mockResolvedValueOnce([{ ...facetResult, byAuthorRoleStage: [] } as unknown as QuestionAggregate]);
      const result = await repositories.question.getStats();

      expect(result.byAuthorRole).toStrictEqual({});
    });

    it("should return empty record for byRejectionType when byRejectionTypeStage is empty.", async() => {
      mocks.models.question.aggregate.mockResolvedValueOnce([{ ...facetResult, byRejectionTypeStage: [] } as unknown as QuestionAggregate]);
      const result = await repositories.question.getStats();

      expect(result.byRejectionType).toStrictEqual({});
    });

    it("should return fullyTranslated count from the $facet result when called.", async() => {
      mocks.models.question.aggregate.mockResolvedValueOnce([facetResult as unknown as QuestionAggregate]);
      const result = await repositories.question.getStats();

      expect(result.byTranslationCompleteness.fullyTranslated).toBe(4);
    });

    it("should return incomplete count from the $facet result when called.", async() => {
      mocks.models.question.aggregate.mockResolvedValueOnce([facetResult as unknown as QuestionAggregate]);
      const result = await repositories.question.getStats();

      expect(result.byTranslationCompleteness.incomplete).toBe(1);
    });

    it("should return zero for fullyTranslated and incomplete when translation count stages are empty.", async() => {
      mocks.models.question.aggregate.mockResolvedValueOnce([
        {
          ...facetResult,
          fullyTranslatedCountStage: [],
          incompleteTranslationCountStage: [],
        } as unknown as QuestionAggregate,
      ]);
      const result = await repositories.question.getStats();

      expect(result.byTranslationCompleteness).toStrictEqual({ fullyTranslated: 0, incomplete: 0 });
    });
  });
});

