        value: "pending",
        expected: true,
      },
      {
        test: "should return true when status is 'active'",
        value: "active",
        expected: true,
      },
      {
        test: "should return true when status is 'rejected'",
        value: "rejected",
        expected: true,
      },
      {
        test: "should return true when status is 'archived'",
        value: "archived",
        expected: true,
      },
      {
        test: "should return false when status is 'deleted'",
