import { ConfigService } from "@nestjs/config";
import { Test } from "@nestjs/testing";

import * as authHelpers from "@src/infrastructure/api/auth/helpers/auth.helpers";
import { AppConfigService } from "@src/infrastructure/api/config/providers/services/app-config.service";

import { createMockedNestConfigService } from "@mocks/infrastructure/api/config/providers/services/nest-config.service.mock";

import { createFakeCorsConfigFromEnv, createFakeLocalizationConfigFromEnv, createFakeMongoDatabaseConfigFromEnv, createFakeServerConfigFromEnv } from "@faketories/infrastructure/api/config/config.faketory";

import type { MockInstance } from "vitest";
import type { TestingModule } from "@nestjs/testing";

import type { AuthenticationConfigFromEnv } from "@src/infrastructure/api/config/types/config.types";

describe(AppConfigService, () => {
  let services: { appConfig: AppConfigService };
  let mocks: {
    services: {
      nestConfig: ReturnType<typeof createMockedNestConfigService>;
    };
    helpers: {
      hashApiKey: MockInstance<typeof authHelpers.hashApiKey>;
      createApiKeyValidator: MockInstance<typeof authHelpers.createApiKeyValidator>;
    };
  };

  beforeEach(async() => {
    const apiKeyHmacSecret = "valid-hmac-secret-of-sufficient-length";
    const adminApiKey = "valid-admin-api-key-of-sufficient-length";
    const gameApiKey = "valid-game-api-key-of-sufficient-length";

    process.env.API_KEY_HMAC_SECRET = apiKeyHmacSecret;
    process.env.ADMIN_API_KEY = adminApiKey;
    process.env.GAME_API_KEY = gameApiKey;

    mocks = {
      services: {
        nestConfig: createMockedNestConfigService({
          SERVER_HOST: "127.0.0.1",
          SERVER_PORT: 8080,
          CORS_ORIGIN: "everywhere",
          MONGODB_HOST: "localhost",
          MONGODB_PORT: 27_018,
          MONGODB_DATABASE: "goat-it-test",
          FALLBACK_LOCALE: "en",
          API_KEY_HMAC_SECRET: apiKeyHmacSecret,
          ADMIN_API_KEY: adminApiKey,
          GAME_API_KEY: gameApiKey,
        }),
      },
      helpers: {
        hashApiKey: vi.spyOn(authHelpers, "hashApiKey").mockReturnValue("hashed-api-key"),
        createApiKeyValidator: vi.spyOn(authHelpers, "createApiKeyValidator").mockReturnValue(() => true),
      },
    };
    const module: TestingModule = await Test.createTestingModule({
      providers: [
        AppConfigService,
        {
          provide: ConfigService,
          useValue: mocks.services.nestConfig,
        },
      ],
    }).compile();

    services = { appConfig: module.get<AppConfigService>(AppConfigService) };
  });

  describe("serverConfig", () => {
    it("should return server config from env when called.", () => {
      const expectedServerConfig = createFakeServerConfigFromEnv({
        host: "127.0.0.1",
        port: 8080,
      });

      expect(services.appConfig.serverConfig).toStrictEqual(expectedServerConfig);
    });

    it("should throw error when one of the required env vars is not defined.", () => {
      mocks.services.nestConfig.getOrThrow.mockImplementation(() => {
        throw new Error("SERVER_HOST is not defined");
      });

      expect(() => services.appConfig.serverConfig).toThrow("SERVER_HOST is not defined");
    });
  });

  describe("serverBaseUrl", () => {
    it("should return server base url when called.", () => {
      expect(services.appConfig.serverBaseUrl).toBe("http://127.0.0.1:8080");
    });

    it.each<{ test: string; host: string; expectedUrl: string }>([
      {
        test: "should return server base url with https when host includes https scheme.",
        host: "https://0.0.0.0",
        expectedUrl: "https://0.0.0.0:8080",
      },
      {
        test: "should return server base url with http when host includes http scheme.",
        host: "http://127.0.0.0",
        expectedUrl: "http://127.0.0.0:8080",
      },
    ])("$test", ({ host, expectedUrl }) => {
      mocks.services.nestConfig.getOrThrow.mockReturnValueOnce(host);
      mocks.services.nestConfig.getOrThrow.mockReturnValueOnce("8080");

      expect(services.appConfig.serverBaseUrl).toBe(expectedUrl);
    });
  });

  describe("corsConfig", () => {
    it("should return cors config from env when called.", () => {
      const expectedCorsConfig = createFakeCorsConfigFromEnv({
        origin: "everywhere",
      });

      expect(services.appConfig.corsConfig).toStrictEqual(expectedCorsConfig);
    });

    it("should throw error when one of the required env vars is not defined.", () => {
      mocks.services.nestConfig.getOrThrow.mockImplementation(() => {
        throw new Error("CORS_ORIGIN is not defined");
      });

      expect(() => services.appConfig.corsConfig).toThrow("CORS_ORIGIN is not defined");
    });
  });

  describe("mongoDbConfig", () => {
    it("should return mongo database config from env when called.", () => {
      const mongoDatabaseConfig = createFakeMongoDatabaseConfigFromEnv({
        host: "localhost",
        port: 27_018,
        database: "goat-it-test",
      });

      expect(services.appConfig.mongoDbConfig).toStrictEqual(mongoDatabaseConfig);
    });

    it("should throw error when one of the required env vars is not defined.", () => {
      mocks.services.nestConfig.getOrThrow.mockImplementation(() => {
        throw new Error("MONGODB_HOST is not defined");
      });

      expect(() => services.appConfig.mongoDbConfig).toThrow("MONGODB_HOST is not defined");
    });
  });

  describe("localizationConfig", () => {
    it("should return localization config from env when called.", () => {
      const localizationConfig = createFakeLocalizationConfigFromEnv({
        fallbackLocale: "en",
      });

      expect(services.appConfig.localizationConfig).toStrictEqual(localizationConfig);
    });

    it("should throw error when one of the required env vars is not defined.", () => {
      mocks.services.nestConfig.getOrThrow.mockImplementation(() => {
        throw new Error("FALLBACK_LOCALE is not defined");
      });

      expect(() => services.appConfig.localizationConfig).toThrow("FALLBACK_LOCALE is not defined");
    });
  });

  describe("authenticationConfig", () => {
    it("should return authentication config from env when called.", () => {
      expect(services.appConfig.authenticationConfig).toStrictEqual<AuthenticationConfigFromEnv>({
        admin: {
          apiKeyValidator: expect.any(Function) as () => boolean,
        },
        game: {
          apiKeyValidator: expect.any(Function) as () => boolean,
        },
      });
    });
  });

  // Acceptable as private method is accessed via bracket notation for symbol-based describe (U3/HP2).
  // oxlint-disable-next-line typescript/dot-notation
  describe(AppConfigService.prototype["computeAuthenticationConfigCache"], () => {
    it("should throw error when one of the required env vars is not defined.", () => {
      mocks.services.nestConfig.getOrThrow.mockImplementation(() => {
        throw new Error("API_KEY_HMAC_SECRET is not defined");
      });

      expect(() => services.appConfig["computeAuthenticationConfigCache"]()).toThrow("API_KEY_HMAC_SECRET is not defined");
    });

    it.each<{ test: string; callIndex: number; expectedApiKey: string }>([
      {
        test: "should call hashApiKey for adminApiKey when config service is created.",
        callIndex: 1,
        expectedApiKey: "valid-admin-api-key-of-sufficient-length",
      },
      {
        test: "should call hashApiKey for gameApiKey when config service is created.",
        callIndex: 2,
        expectedApiKey: "valid-game-api-key-of-sufficient-length",
      },
    ])("$test", ({ callIndex, expectedApiKey }) => {
      expect(mocks.helpers.hashApiKey).toHaveBeenNthCalledWith(callIndex, expectedApiKey, "valid-hmac-secret-of-sufficient-length");
    });

    it.each<{ test: string; callIndex: number }>([
      {
        test: "should call createApiKeyValidator for adminApiKey when config service is created.",
        callIndex: 1,
      },
      {
        test: "should call createApiKeyValidator for gameApiKey when config service is created.",
        callIndex: 2,
      },
    ])("$test", ({ callIndex }) => {
      expect(mocks.helpers.createApiKeyValidator).toHaveBeenNthCalledWith(callIndex, "hashed-api-key", "valid-hmac-secret-of-sufficient-length");
    });
  });

  // Acceptable as private method is accessed via bracket notation for symbol-based describe (U3/HP2).
  // oxlint-disable-next-line typescript/dot-notation
  describe(AppConfigService["removeSensitiveEnvVariables"], () => {
    it.each<{ test: string; envVarName: string }>([
      {
        test: "should delete api key hmac secret when computing authentication config cache.",
        envVarName: "API_KEY_HMAC_SECRET",
      },
      {
        test: "should delete admin api key when computing authentication config cache.",
        envVarName: "ADMIN_API_KEY",
      },
      {
        test: "should delete game api key when computing authentication config cache.",
        envVarName: "GAME_API_KEY",
      },
    ])("$test", ({ envVarName }) => {
      expect(process.env[envVarName]).toBeUndefined();
    });
  });
});

