import { Test } from "@nestjs/testing";

import { AppConfigService } from "@src/infrastructure/api/config/providers/services/app-config.service";

import * as findAllQueryDtoMappers from "@shared/application/mappers/find-all-query-dto/find-all-query-dto.mappers";

import * as findRandomOptionsMappers from "@question/application/mappers/find-random-options/find-random-options.mappers";
import { FindQuestionByIdUseCase } from "@question/application/use-cases/find-question-by-id/find-question-by-id.use-case";
import { FindRandomQuestionsUseCase } from "@question/application/use-cases/find-random-questions/find-random-questions.use-case";
import { FindQuestionsUseCase } from "@question/application/use-cases/find-questions/find-questions.use-case";
import { QuestionController } from "@question/infrastructure/http/controllers/question/question.controller";
import * as questionMappers from "@question/application/mappers/question.mappers";
import * as questionFilterQueryDtoMappers from "@question/application/mappers/question-filter-query-dto/question-filter-query-dto.mappers";
import { FIND_RANDOM_QUESTIONS_BODY_LIMIT_DEFAULT } from "@question/application/dto/find-random-questions-body/constants/find-random-questions-body.dto.constants";
import type { FindQuestionsQueryDto } from "@question/application/dto/find-questions-query/find-questions-query.dto.shape";

import { createMockedFindQuestionByIdUseCase } from "@mocks/contexts/question/application/use-cases/find-question-by-id.use-case.mock";
import { createMockedFindRandomQuestionsUseCase } from "@mocks/contexts/question/application/use-cases/find-random-questions.use-case.mock";
import { createMockedAppConfigService } from "@mocks/infrastructure/api/config/providers/services/app-config.service.mock";
import { createMockedFindQuestionsUseCase } from "@mocks/contexts/question/application/use-cases/find-questions.use-case.mock";

import { createFakeQuestion } from "@faketories/contexts/question/entity/question.entity.faketory";
import { createFakeLocalizationOptions } from "@faketories/shared/locale/locale.faketory";
import { createFakeFindQuestionsQueryDto } from "@faketories/contexts/question/dto/find-questions-query/find-questions-query.dto.faketory";
import { createFakeFindRandomQuestionsBodyDto } from "@faketories/contexts/question/dto/find-random-questions-body/find-random-questions-body.dto.faketory";

import type { Mock } from "vitest";

import type { FindAllOptions } from "@shared/domain/types/find/find.types";
import type { QuestionFilterOptions, QuestionSortableField, FindRandomQuestionsOptions } from "@question/domain/types/question.types";

describe(QuestionController, () => {
  let questionController: QuestionController;
  let mocks: {
    services: {
      appConfig: ReturnType<typeof createMockedAppConfigService>;
    };
    useCases: {
      findQuestions: ReturnType<typeof createMockedFindQuestionsUseCase>;
      findRandomQuestions: ReturnType<typeof createMockedFindRandomQuestionsUseCase>;
      findQuestionById: ReturnType<typeof createMockedFindQuestionByIdUseCase>;
    };
    mappers: {
      createQuestionDtoFromEntity: Mock;
      createFindAllOptionsFromQueryDto: Mock;
      createFindRandomQuestionsOptionsFromBodyDto: Mock;
    };
  };

  beforeEach(async() => {
    mocks = {
      services: {
        appConfig: createMockedAppConfigService(),
      },
      useCases: {
        findQuestions: createMockedFindQuestionsUseCase(),
        findRandomQuestions: createMockedFindRandomQuestionsUseCase(),
        findQuestionById: createMockedFindQuestionByIdUseCase(),
      },
      mappers: {
        createQuestionDtoFromEntity: vi.spyOn(questionMappers, "createQuestionDtoFromEntity").mockImplementation(vi.fn()),
        createFindAllOptionsFromQueryDto: vi.spyOn(findAllQueryDtoMappers, "createFindAllOptionsFromQueryDto").mockImplementation(vi.fn()),
        createFindRandomQuestionsOptionsFromBodyDto: vi.spyOn(findRandomOptionsMappers, "createFindRandomQuestionsOptionsFromBodyDto").mockImplementation(vi.fn()),
      },
    };

    const testingModule = await Test.createTestingModule({
      controllers: [QuestionController],
      providers: [
        {
          provide: AppConfigService,
          useValue: mocks.services.appConfig,
        },
        {
          provide: FindQuestionsUseCase,
          useValue: mocks.useCases.findQuestions,
        },
        {
          provide: FindQuestionByIdUseCase,
          useValue: mocks.useCases.findQuestionById,
        },
        {
          provide: FindRandomQuestionsUseCase,
          useValue: mocks.useCases.findRandomQuestions,
        },
      ],
    }).compile();

    questionController = testingModule.get<QuestionController>(QuestionController);
  });

  describe(QuestionController.prototype.findQuestions, () => {
    it("should create find all options from query dto and locale-aware mapper when called.", async() => {
      const queryDto = createFakeFindQuestionsQueryDto();
      const localization = createFakeLocalizationOptions();
      await questionController.findQuestions(queryDto, localization);

      expect(mocks.mappers.createFindAllOptionsFromQueryDto).toHaveBeenCalledExactlyOnceWith(queryDto, expect.any(Function));
    });

    it("should call public filter mapper with query dto and localization locale when finding questions.", async() => {
      const queryDto = createFakeFindQuestionsQueryDto();
      const localization = createFakeLocalizationOptions();
      const createPublicQuestionFilterOptionsFromQueryDtoSpy = vi.spyOn(questionFilterQueryDtoMappers, "createPublicQuestionFilterOptionsFromQueryDto");

      type FilterMapper = (dto: FindQuestionsQueryDto) => Partial<QuestionFilterOptions> | undefined;

      mocks.mappers.createFindAllOptionsFromQueryDto.mockImplementation((dto: FindQuestionsQueryDto, mapper: FilterMapper) => mapper(dto));

      await questionController.findQuestions(queryDto, localization);

      expect(createPublicQuestionFilterOptionsFromQueryDtoSpy).toHaveBeenCalledExactlyOnceWith(queryDto, localization.locale);
    });

    it("should list all questions with find all options when called.", async() => {
      const queryDto = createFakeFindQuestionsQueryDto();
      const localization = createFakeLocalizationOptions();
      const expectedFindAllOptions: FindAllOptions<QuestionSortableField, QuestionFilterOptions> = { sort: { sortBy: "createdAt", sortOrder: "desc" } };
      mocks.mappers.createFindAllOptionsFromQueryDto.mockReturnValueOnce(expectedFindAllOptions);
      await questionController.findQuestions(queryDto, localization);

      expect(mocks.useCases.findQuestions.list).toHaveBeenCalledExactlyOnceWith(expectedFindAllOptions);
    });

    it("should propagate ids through to the use case when ids is provided in the query dto.", async() => {
      const ids = ["618c1f4b3a2f000000000030", "618c1f4b3a2f000000000031"];
      const queryDto = { ...createFakeFindQuestionsQueryDto(), ids } as FindQuestionsQueryDto;
      const localization = createFakeLocalizationOptions();

      type FilterMapper = (dto: FindQuestionsQueryDto) => Partial<QuestionFilterOptions> | undefined;

      mocks.mappers.createFindAllOptionsFromQueryDto.mockImplementation((dto: FindQuestionsQueryDto, mapper: FilterMapper) => {
        const filters = mapper(dto);

        return { sort: { sortBy: "createdAt", sortOrder: "desc" }, filters, limit: 10 };
      });

      await questionController.findQuestions(queryDto, localization);

      const expectedCall = {
        // Acceptable as expect.objectContaining returns any from Vitest types
        // oxlint-disable-next-line typescript/no-unsafe-assignment
        filters: expect.objectContaining({ ids }),
      };

      expect(mocks.useCases.findQuestions.list).toHaveBeenCalledExactlyOnceWith(expect.objectContaining(expectedCall));
    });

    it("should map every question to dto when called.", async() => {
      const queryDto = createFakeFindQuestionsQueryDto();
      const localization = createFakeLocalizationOptions();
      const questions = [
        createFakeQuestion(),
        createFakeQuestion(),
        createFakeQuestion(),
      ];
      mocks.useCases.findQuestions.list.mockResolvedValueOnce(questions);
      await questionController.findQuestions(queryDto, localization);

      expect(mocks.mappers.createQuestionDtoFromEntity).toHaveBeenCalledTimes(questions.length);
    });

    it("should call the mapper with the correct parameters when called.", async() => {
      const queryDto = createFakeFindQuestionsQueryDto();
      const localization = createFakeLocalizationOptions();
      const questions = [
        createFakeQuestion(),
        createFakeQuestion(),
        createFakeQuestion(),
      ];
      mocks.useCases.findQuestions.list.mockResolvedValueOnce(questions);

      await questionController.findQuestions(queryDto, localization);

      expect(mocks.mappers.createQuestionDtoFromEntity).toHaveBeenCalledWith(questions[0], localization);
    });
  });

  describe(QuestionController.prototype.findQuestionById, () => {
    it("should get question by id when called.", async() => {
      const localization = createFakeLocalizationOptions();
      const questionId = "123";
      await questionController.findQuestionById(questionId, localization);

      expect(mocks.useCases.findQuestionById.getById).toHaveBeenCalledExactlyOnceWith(questionId);
    });

    it("should map the question to dto when called.", async() => {
      const localization = createFakeLocalizationOptions();
      const questionId = "123";
      const question = createFakeQuestion();
      mocks.useCases.findQuestionById.getById.mockResolvedValueOnce(question);
      await questionController.findQuestionById(questionId, localization);

      expect(mocks.mappers.createQuestionDtoFromEntity).toHaveBeenCalledExactlyOnceWith(question, localization);
    });
  });

  describe(QuestionController.prototype.findRandomQuestions, () => {
    it.each<number>([5, FIND_RANDOM_QUESTIONS_BODY_LIMIT_DEFAULT])("should create find random options from body dto and locale when called with limit %s.", async expectedLimit => {
      const bodyDto = createFakeFindRandomQuestionsBodyDto({ limit: expectedLimit });
      const localization = createFakeLocalizationOptions();

      await questionController.findRandomQuestions(bodyDto, localization);

      expect(mocks.mappers.createFindRandomQuestionsOptionsFromBodyDto).toHaveBeenCalledExactlyOnceWith(bodyDto, localization.locale);
    });

    it.each<number>([5, FIND_RANDOM_QUESTIONS_BODY_LIMIT_DEFAULT])("should list random questions with limit %s and locale when called.", async expectedLimit => {
      const bodyDto = createFakeFindRandomQuestionsBodyDto({ limit: expectedLimit });
      const localization = createFakeLocalizationOptions();
      const expectedOptions: FindRandomQuestionsOptions = { limit: expectedLimit, locale: localization.locale };
      mocks.mappers.createFindRandomQuestionsOptionsFromBodyDto.mockReturnValueOnce(expectedOptions);

      await questionController.findRandomQuestions(bodyDto, localization);

      expect(mocks.useCases.findRandomQuestions.list).toHaveBeenCalledExactlyOnceWith(expectedOptions);
    });

    it("should map every question to dto when called.", async() => {
      const bodyDto = createFakeFindRandomQuestionsBodyDto();
      const localization = createFakeLocalizationOptions();
      const questions = [
        createFakeQuestion(),
        createFakeQuestion(),
        createFakeQuestion(),
      ];
      mocks.useCases.findRandomQuestions.list.mockResolvedValueOnce(questions);
      await questionController.findRandomQuestions(bodyDto, localization);

      expect(mocks.mappers.createQuestionDtoFromEntity).toHaveBeenCalledTimes(questions.length);
    });

    it("should call the mapper with the correct parameters when called.", async() => {
      const bodyDto = createFakeFindRandomQuestionsBodyDto();
      const localization = createFakeLocalizationOptions();
      const questions = [
        createFakeQuestion(),
        createFakeQuestion(),
        createFakeQuestion(),
      ];
      mocks.useCases.findRandomQuestions.list.mockResolvedValueOnce(questions);

      await questionController.findRandomQuestions(bodyDto, localization);

      expect(mocks.mappers.createQuestionDtoFromEntity).toHaveBeenCalledWith(questions[0], localization);
    });
  });
});

