import { FindQuestionByIdUseCase } from "@question/application/use-cases/find-question-by-id/find-question-by-id.use-case";
import { QuestionPrimaryThemeAssignmentNotRemovableError } from "@question/domain/errors/question-primary-theme-assignment-not-removable/question-primary-theme-assignment-not-removable.error";
import { QuestionThemeAssignmentAbsentError } from "@question/domain/errors/question-theme-assignment-absent/question-theme-assignment-absent.error";
import { QuestionThemeAssignmentRemovalError } from "@question/domain/errors/question-theme-assignment-removal/question-theme-assignment-removal.error";
import { QuestionMinimumThemesError } from "@question/domain/errors/question-minimum-themes/question-minimum-themes.error";
import { RemoveThemeFromQuestionUseCase } from "@question/application/use-cases/question-theme-assignment/remove-theme-from-question/remove-theme-from-question.use-case";

import { createMockedQuestionRepository } from "@mocks/contexts/question/domain/repositories/question.repository.mock";
import { createMockedFindQuestionByIdUseCase } from "@mocks/contexts/question/application/use-cases/find-question-by-id.use-case.mock";

import { createFakeQuestionThemeAssignmentRemovalCommand } from "@faketories/contexts/question/commands/question-theme-assignment/commands/question-theme-assignment.commands.faketory";
import { createFakeQuestionTheme } from "@faketories/contexts/question-theme/entity/question-theme.entity.faketory";
import { createFakeQuestion, createFakeQuestionThemeAssignment } from "@faketories/contexts/question/entity/question.entity.faketory";

describe(RemoveThemeFromQuestionUseCase, () => {
  let useCase: RemoveThemeFromQuestionUseCase;
  let mocks: {
    repositories: {
      question: ReturnType<typeof createMockedQuestionRepository>;
    };
    useCases: {
      findQuestionById: ReturnType<typeof createMockedFindQuestionByIdUseCase>;
    };
  };

  beforeEach(() => {
    mocks = {
      repositories: {
        question: createMockedQuestionRepository(),
      },
      useCases: {
        findQuestionById: createMockedFindQuestionByIdUseCase(),
      },
    };

    useCase = new RemoveThemeFromQuestionUseCase(
      mocks.repositories.question,
      mocks.useCases.findQuestionById as unknown as FindQuestionByIdUseCase,
    );
  });

  describe(RemoveThemeFromQuestionUseCase.prototype.remove, () => {
    it("should throw QuestionThemeAssignmentRemovalError when repository returns undefined.", async() => {
      const command = createFakeQuestionThemeAssignmentRemovalCommand({
        questionId: "q3",
        themeId: "theme-1",
      });
      const question = createFakeQuestion({
        id: "q3",
        themes: [
          createFakeQuestionThemeAssignment({
            theme: createFakeQuestionTheme({ id: "theme-1" }),
            isPrimary: false,
          }),
          createFakeQuestionThemeAssignment({
            theme: createFakeQuestionTheme({ id: "theme-2" }),
            isPrimary: false,
          }),
        ],
      });
      vi.mocked(mocks.useCases.findQuestionById.getById).mockResolvedValueOnce(question);
      vi.mocked(mocks.repositories.question.removeTheme).mockResolvedValueOnce(undefined);
      const expectedError = new QuestionThemeAssignmentRemovalError(command.themeId, command.questionId);

      await expect(useCase.remove(command)).rejects.toThrow(expectedError);
    });

    it("should call repository remove method when called.", async() => {
      const command = createFakeQuestionThemeAssignmentRemovalCommand({
        questionId: "q3",
        themeId: "theme-1",
      });
      const question = createFakeQuestion({
        id: "q3",
        themes: [
          createFakeQuestionThemeAssignment({
            theme: createFakeQuestionTheme({ id: "theme-1" }),
            isPrimary: false,
          }),
          createFakeQuestionThemeAssignment({
            theme: createFakeQuestionTheme({ id: "theme-2" }),
            isPrimary: false,
          }),
        ],
      });
      vi.mocked(mocks.useCases.findQuestionById.getById).mockResolvedValueOnce(question);
      const updated = createFakeQuestion();
      vi.mocked(mocks.repositories.question.removeTheme).mockResolvedValueOnce(updated);

      await useCase.remove(command);

      expect(mocks.repositories.question.removeTheme).toHaveBeenCalledExactlyOnceWith(command.questionId, command.themeId);
    });

    it("should return updated question when repository succeeds.", async() => {
      const command = createFakeQuestionThemeAssignmentRemovalCommand({
        questionId: "q3",
        themeId: "theme-1",
      });
      const question = createFakeQuestion({
        id: "q3",
        themes: [
          createFakeQuestionThemeAssignment({
            theme: createFakeQuestionTheme({ id: "theme-1" }),
            isPrimary: false,
          }),
          createFakeQuestionThemeAssignment({
            theme: createFakeQuestionTheme({ id: "theme-2" }),
            isPrimary: false,
          }),
        ],
      });
      vi.mocked(mocks.useCases.findQuestionById.getById).mockResolvedValueOnce(question);
      const updated = createFakeQuestion();
      vi.mocked(mocks.repositories.question.removeTheme).mockResolvedValueOnce(updated);

      const result = await useCase.remove(command);

      expect(result).toStrictEqual(updated);
    });
  });

  describe("throwIfThemeNotRemovableFromQuestion", () => {
    it("should throw QuestionMinimumThemesError when question has minimum themes.", async() => {
      const command = createFakeQuestionThemeAssignmentRemovalCommand({
        questionId: "q1",
        themeId: "existing-theme",
      });
      const question = createFakeQuestion({
        id: "q1",
        themes: [
          createFakeQuestionThemeAssignment({
            theme: createFakeQuestionTheme({ id: "existing-theme" }),
            isPrimary: false,
          }),
        ],
      });
      vi.mocked(mocks.useCases.findQuestionById.getById).mockResolvedValueOnce(question);
      const expectedError = new QuestionMinimumThemesError(command.questionId);

      await expect(useCase["throwIfThemeNotRemovableFromQuestion"](command.questionId, command.themeId)).rejects.toThrow(expectedError);
    });

    it("should throw QuestionThemeAssignmentAbsentError when question has no themes.", async() => {
      const command = createFakeQuestionThemeAssignmentRemovalCommand({
        questionId: "q0",
        themeId: "missing-theme",
      });
      const question = createFakeQuestion({
        id: "q0",
        themes: [],
      });
      vi.mocked(mocks.useCases.findQuestionById.getById).mockResolvedValueOnce(question);
      const expectedError = new QuestionThemeAssignmentAbsentError(command.themeId, command.questionId);

      await expect(useCase["throwIfThemeNotRemovableFromQuestion"](command.questionId, command.themeId)).rejects.toThrow(expectedError);
    });

    it("should throw QuestionThemeAssignmentAbsentError when theme not assigned.", async() => {
      const command = createFakeQuestionThemeAssignmentRemovalCommand({
        questionId: "q2",
        themeId: "missing-theme",
      });
      const question = createFakeQuestion({
        id: "q2",
        themes: [
          createFakeQuestionThemeAssignment({
            theme: createFakeQuestionTheme({ id: "existing-theme" }),
          }),
          createFakeQuestionThemeAssignment({
            theme: createFakeQuestionTheme({ id: "existing-theme-2" }),
          }),
        ],
      });
      vi.mocked(mocks.useCases.findQuestionById.getById).mockResolvedValueOnce(question);
      const expectedError = new QuestionThemeAssignmentAbsentError(command.themeId, command.questionId);

      await expect(useCase["throwIfThemeNotRemovableFromQuestion"](command.questionId, command.themeId)).rejects.toThrow(expectedError);
    });

    it("should throw QuestionPrimaryThemeAssignmentNotRemovableError when theme is primary.", async() => {
      const command = createFakeQuestionThemeAssignmentRemovalCommand({
        questionId: "q-primary",
        themeId: "primary-theme",
      });
      const question = createFakeQuestion({
        id: "q-primary",
        themes: [
          createFakeQuestionThemeAssignment({
            theme: createFakeQuestionTheme({ id: "primary-theme" }),
            isPrimary: true,
          }),
          createFakeQuestionThemeAssignment({
            theme: createFakeQuestionTheme({ id: "other-theme" }),
            isPrimary: false,
          }),
        ],
      });
      vi.mocked(mocks.useCases.findQuestionById.getById).mockResolvedValueOnce(question);
      const expectedError = new QuestionPrimaryThemeAssignmentNotRemovableError(command.themeId, command.questionId);

      await expect(useCase["throwIfThemeNotRemovableFromQuestion"](command.questionId, command.themeId)).rejects.toThrow(expectedError);
    });
  });
});

import { DEFAULT_QUESTION_THEME_STATUS, QUESTION_THEME_STATUS_ARCHIVED } from "@question-theme/domain/constants/question-theme.constants";
import { GetQuestionThemesByIdsOrThrowUseCase } from "@question-theme/application/use-cases/get-question-themes-by-ids-or-throw/get-question-themes-by-ids-or-throw.use-case";

import { CreateQuestionUseCase } from "@question/application/use-cases/create-question/create-question.use-case";
import { QuestionCreationError } from "@question/domain/errors/question-creation/question-creation.error";
import { ReferencedQuestionThemeArchivedError } from "@question/domain/errors/referenced-question-theme-archived/referenced-question-theme-archived.error";

import { createMockedGetQuestionThemesByIdsOrThrowUseCase } from "@mocks/contexts/question-theme/application/use-cases/get-question-themes-by-ids-or-throw.use-case.mock";
import { createMockedQuestionRepository } from "@mocks/contexts/question/domain/repositories/question.repository.mock";

import { createFakeQuestion } from "@faketories/contexts/question/entity/question.entity.faketory";
import { createFakeQuestionCreationCommand } from "@faketories/contexts/question/commands/question.commands.faketory";
import { createFakeQuestionTheme } from "@faketories/contexts/question-theme/entity/question-theme.entity.faketory";

describe(CreateQuestionUseCase, () => {
  let createQuestionUseCase: CreateQuestionUseCase;
  let mocks: {
    repositories: {
      question: ReturnType<typeof createMockedQuestionRepository>;
    };
    useCases: {
      getQuestionThemesByIdsOrThrow: ReturnType<typeof createMockedGetQuestionThemesByIdsOrThrowUseCase>;
    };
  };

  beforeEach(() => {
    mocks = {
      repositories: {
        question: createMockedQuestionRepository(),
      },
      useCases: {
        getQuestionThemesByIdsOrThrow: createMockedGetQuestionThemesByIdsOrThrowUseCase(),
      },
    };
    mocks.useCases.getQuestionThemesByIdsOrThrow.getByIdsOrThrow.mockResolvedValue([
      createFakeQuestionTheme({ status: DEFAULT_QUESTION_THEME_STATUS }),
      createFakeQuestionTheme({ status: DEFAULT_QUESTION_THEME_STATUS }),
    ]);

    createQuestionUseCase = new CreateQuestionUseCase(
      mocks.repositories.question,
      mocks.useCases.getQuestionThemesByIdsOrThrow as unknown as GetQuestionThemesByIdsOrThrowUseCase,
    );
  });

  describe(CreateQuestionUseCase.prototype.create, () => {
    it("should call repository.create with payload when called.", async() => {
      const command = createFakeQuestionCreationCommand();

      await createQuestionUseCase.create(command);

      expect(mocks.repositories.question.create).toHaveBeenCalledExactlyOnceWith(command.payload);
    });

    it("should throw QuestionCreationError when repository returns undefined.", async() => {
      const command = createFakeQuestionCreationCommand();
      mocks.repositories.question.create.mockResolvedValueOnce(undefined);
      const expectedError = new QuestionCreationError();

      await expect(createQuestionUseCase.create(command)).rejects.toThrow(expectedError);
    });

    it("should return created question when repository returns one.", async() => {
      const command = createFakeQuestionCreationCommand();
      const expected = createFakeQuestion();
      mocks.repositories.question.create.mockResolvedValueOnce(expected);

      const actual = await createQuestionUseCase.create(command);

      expect(actual).toStrictEqual(expected);
    });

    it("should call throwIfQuestionNotCreatable with command when called.", async() => {
      const command = createFakeQuestionCreationCommand();
      const throwIfQuestionNotCreatableSpy = vi.spyOn(createQuestionUseCase as unknown as { throwIfQuestionNotCreatable: () => Promise<void> }, "throwIfQuestionNotCreatable");
      await createQuestionUseCase.create(command);

      expect(throwIfQuestionNotCreatableSpy).toHaveBeenCalledExactlyOnceWith(command);
    });
  });

  describe("throwIfQuestionNotCreatable", () => {
    it("should call getQuestionThemesByIdsOrThrow.getByIdsOrThrow with theme ids when called.", async() => {
      const command = createFakeQuestionCreationCommand();
      const expectedThemeIds = new Set(command.payload.themes.map(themeAssignment => themeAssignment.themeId));

      await createQuestionUseCase["throwIfQuestionNotCreatable"](command);

      expect(mocks.useCases.getQuestionThemesByIdsOrThrow.getByIdsOrThrow).toHaveBeenCalledExactlyOnceWith(expectedThemeIds);
    });

    it("should not throw when all referenced themes exist and are not archived.", async() => {
      const command = createFakeQuestionCreationCommand();

      await expect(createQuestionUseCase["throwIfQuestionNotCreatable"](command)).resolves.not.toThrow();
    });

    it("should throw ReferencedQuestionThemeArchivedError when some referenced theme is archived.", async() => {
      const command = createFakeQuestionCreationCommand();
      const archivedThemeId = command.payload.themes[0].themeId;
      mocks.useCases.getQuestionThemesByIdsOrThrow.getByIdsOrThrow.mockResolvedValueOnce([
        createFakeQuestionTheme({
          id:
          archivedThemeId,
          status: QUESTION_THEME_STATUS_ARCHIVED,
        }),
      ]);
      const expectedError = new ReferencedQuestionThemeArchivedError(archivedThemeId);

      await expect(createQuestionUseCase["throwIfQuestionNotCreatable"](command)).rejects.toThrow(expectedError);
    });
  });
});

