    mappers: {
      createAdminQuestionThemeDtoFromEntity: Mock;
      createQuestionThemeCreationCommandFromDto: Mock;
      createQuestionThemeModificationCommandFromDto: Mock;
      createFindAllOptionsFromQueryDto: Mock;
    };
  };

  beforeEach(async() => {
    mocks = {
      services: {
        appConfig: createMockedAppConfigService(),
      },
      useCases: {
        findQuestionThemes: createMockedFindQuestionThemesUseCase(),
        findQuestionThemeById: createMockedFindQuestionThemeByIdUseCase(),
        createQuestionTheme: createMockedCreateQuestionThemeUseCase(),
        getQuestionThemeStats: createMockedGetQuestionThemeStatsUseCase(),
        modifyQuestionTheme: createMockedModifyQuestionThemeUseCase(),
        archiveQuestionTheme: createMockedArchiveQuestionThemeUseCase(),
      },
      mappers: {
        createAdminQuestionThemeDtoFromEntity: vi.spyOn(questionThemeContractMappers, "createAdminQuestionThemeDtoFromEntity").mockImplementation(vi.fn()),
        createQuestionThemeCreationCommandFromDto: vi.spyOn(questionThemeMappers, "createQuestionThemeCreationCommandFromDto").mockImplementation(vi.fn()),
        createQuestionThemeModificationCommandFromDto: vi.spyOn(questionThemeMappers, "createQuestionThemeModificationCommandFromDto").mockImplementation(vi.fn()),
        createFindAllOptionsFromQueryDto: vi.spyOn(findAllQueryDtoMappers, "createFindAllOptionsFromQueryDto").mockImplementation(vi.fn()),
      },
    };
    const testingModule = await Test.createTestingModule({
      controllers: [AdminQuestionThemeController],
      providers: [
        {
          provide: AppConfigService,
          useValue: mocks.services.appConfig,
        },
        {
          provide: FindQuestionThemesUseCase,
          useValue: mocks.useCases.findQuestionThemes,
        },
        {
          provide: FindQuestionThemeByIdUseCase,
          useValue: mocks.useCases.findQuestionThemeById,
        },
        {
          provide: CreateQuestionThemeUseCase,
          useValue: mocks.useCases.createQuestionTheme,
        },
        {
          provide: GetQuestionThemeStatsUseCase,
          useValue: mocks.useCases.getQuestionThemeStats,
        },
        {
          provide: ModifyQuestionThemeUseCase,
          useValue: mocks.useCases.modifyQuestionTheme,
        },
        {
          provide: ArchiveQuestionThemeUseCase,
          useValue: mocks.useCases.archiveQuestionTheme,
        },
      ],
    }).compile();

    adminQuestionThemeController = testingModule.get<AdminQuestionThemeController>(AdminQuestionThemeController);
  });

  describe(AdminQuestionThemeController.prototype.findQuestionThemes, () => {
    it("should create find all options from query dto when called.", async() => {
      const queryDto = createFakeAdminFindQuestionThemesQueryDto();
      await adminQuestionThemeController.findQuestionThemes(queryDto);

      expect(mocks.mappers.createFindAllOptionsFromQueryDto).toHaveBeenCalledExactlyOnceWith(queryDto, createAdminQuestionThemeFilterOptionsFromQueryDto);
    });

    it("should list all question themes with find all options when called.", async() => {
      const queryDto = createFakeAdminFindQuestionThemesQueryDto();
      const expectedFindAllOptions: FindAllOptions<QuestionThemeSortableField, AdminQuestionThemeFilterOptions> = { sort: { sortBy: "createdAt", sortOrder: "desc" } };
      mocks.mappers.createFindAllOptionsFromQueryDto.mockReturnValueOnce(expectedFindAllOptions);
      await adminQuestionThemeController.findQuestionThemes(queryDto);

      expect(mocks.useCases.findQuestionThemes.list).toHaveBeenCalledExactlyOnceWith(expectedFindAllOptions);
    });

    it("should map every question theme to admin dto when called.", async() => {
      const queryDto = createFakeAdminFindQuestionThemesQueryDto();
      const questionThemes = [
        createFakeQuestionTheme(),
        createFakeQuestionTheme(),
        createFakeQuestionTheme(),
      ];
      mocks.useCases.findQuestionThemes.list.mockResolvedValueOnce(questionThemes);
      await adminQuestionThemeController.findQuestionThemes(queryDto);

      expect(mocks.mappers.createAdminQuestionThemeDtoFromEntity).toHaveBeenCalledTimes(questionThemes.length);
    });

    it("should call the mapper with the correct parameters when called.", async() => {
