                  {
                    $map: {
                      input: {
                        $cond: [
                          { $eq: [{ $size: { $ifNull: ["$applicableLocales", []] } }, 0] },
                          LOCALES,
                          "$applicableLocales",
                        ],
                      },
                      as: "locale",
                      in: { $gt: [{ $getField: { field: "$$locale", input: "$content.statement" } }, null] },
                    },
                  },
                ],
              },
              {
                $allElementsTrue: [
                  {
                    $map: {
                      input: {
                        $cond: [
                          { $eq: [{ $size: { $ifNull: ["$applicableLocales", []] } }, 0] },
                          LOCALES,
                          "$applicableLocales",
                        ],
                      },
                      as: "locale",
                      in: { $gt: [{ $getField: { field: "$$locale", input: "$content.answer" } }, null] },
                    },
                  },
                ],
              },
              {
                $or: [
                  { $not: { $gt: ["$content.context", null] } },
                  {
                    $allElementsTrue: [
                      {
                        $map: {
