                  {
                    $allElementsTrue: [
                      {
                        $map: {
                          input: {
                            $cond: [
                              { $eq: [{ $size: { $ifNull: ["$applicableLocales", []] } }, 0] },
                              LOCALES,
                              "$applicableLocales",
                            ],
                          },
                          as: "locale",
                          in: { $gt: [{ $getField: { field: "$$locale", input: "$content.trivia" } }, null] },
                        },
                      },
                    ],
                  },
                ],
              },
            ],
          },
        },
      },
    ]);
  });

  it.each<{ name: string; filters: Partial<QuestionFilterOptions>; expected: Record<string, unknown> }>([
