      expect(() => ADMIN_QUESTION_DTO.parse(dtoWithInvalidSourceUrls)).toThrow(ZodError);
    });

    it("should have correct metadata when accessing the metadata.", () => {
      const metadata = ADMIN_QUESTION_DTO.shape.sourceUrls.meta();
