import { ZodError } from "zod";

import { API_RESPONSE_EXCEPTION_DTO } from "@shared/application/dto/api-response-exception/api-response-exception.dto.shape";

describe("Api Response Exception DTO Shape", () => {
  let validApiResponseExceptionDto: {
    statusCode: number;
    message: string;
    error: string;
    validationDetails?: { code: string; message: string; path: (string | number)[] }[];
    errorCode?: string;
  };

  beforeEach(() => {
    validApiResponseExceptionDto = {
      statusCode: 400,
      message: "The request could not be understood by the server due to malformed syntax.",
      error: "Bad Request",
      validationDetails: [{ code: "type_error", message: "Expected type string but received type number", path: ["user", "age"] }],
      errorCode: "bad-request",
    };
  });

  it("should pass validation when assigned valid values.", () => {
    expect(() => API_RESPONSE_EXCEPTION_DTO.parse(validApiResponseExceptionDto)).not.toThrow();
  });

  describe("statusCode", () => {
    it("should throw a zod error when assigned a non-number value.", () => {
      const invalidDto = { ...validApiResponseExceptionDto, statusCode: "invalid" };

      expect(() => API_RESPONSE_EXCEPTION_DTO.parse(invalidDto)).toThrow(ZodError);
    });

    it("should have correct description when accessing the description.", () => {
      expect(API_RESPONSE_EXCEPTION_DTO.shape.statusCode.description).toBe("HTTP status code of the error response");
    });

    it("should have correct metadata when accessing the metadata.", () => {
      const expectedMetadata = {
        description: "HTTP status code of the error response",
        example: 400,
      };

      expect(API_RESPONSE_EXCEPTION_DTO.shape.statusCode.meta()).toStrictEqual<Record<string, unknown>>(expectedMetadata);
    });
  });

  describe("message", () => {
    it("should throw a zod error when assigned a non-string value.", () => {
      const invalidDto = { ...validApiResponseExceptionDto, message: 123 };

      expect(() => API_RESPONSE_EXCEPTION_DTO.parse(invalidDto)).toThrow(ZodError);
    });

    it("should have correct description when accessing the description.", () => {
      expect(API_RESPONSE_EXCEPTION_DTO.shape.message.description).toBe("Error message");
    });

    it("should have correct metadata when accessing the metadata.", () => {
      const expectedMetadata = {
        description: "Error message",
        example: "The request could not be understood by the server due to malformed syntax.",
      };

      expect(API_RESPONSE_EXCEPTION_DTO.shape.message.meta()).toStrictEqual<Record<string, unknown>>(expectedMetadata);
    });
  });

  describe("error", () => {
    it("should throw a zod error when assigned a non-string value.", () => {
      const invalidDto = { ...validApiResponseExceptionDto, error: 123 };

      expect(() => API_RESPONSE_EXCEPTION_DTO.parse(invalidDto)).toThrow(ZodError);
    });

    it("should have correct description when accessing the description.", () => {
      expect(API_RESPONSE_EXCEPTION_DTO.shape.error.description).toBe("Short description of the HTTP error");
    });

    it("should have correct metadata when accessing the metadata.", () => {
      const expectedMetadata = {
        description: "Short description of the HTTP error",
        example: "Bad Request",
      };

      expect(API_RESPONSE_EXCEPTION_DTO.shape.error.meta()).toStrictEqual<Record<string, unknown>>(expectedMetadata);
    });
  });

  describe("validationDetails", () => {
    it("should throw a zod error when assigned a non-array value.", () => {
      const invalidDto = { ...validApiResponseExceptionDto, validationDetails: "invalid" };

      expect(() => API_RESPONSE_EXCEPTION_DTO.parse(invalidDto)).toThrow(ZodError);
    });

    it("should have correct description when accessing the description.", () => {
      expect(API_RESPONSE_EXCEPTION_DTO.shape.validationDetails.description).toBe("List of validation errors, when requested DTO validation fails");
    });
  });

  describe("errorCode", () => {
    it("should throw a zod error when assigned a non-string value.", () => {
      const invalidDto = { ...validApiResponseExceptionDto, errorCode: 123 };

      expect(() => API_RESPONSE_EXCEPTION_DTO.parse(invalidDto)).toThrow(ZodError);
    });

    it("should have correct description when accessing the description.", () => {
      expect(API_RESPONSE_EXCEPTION_DTO.shape.errorCode.description).toBe("Machine-readable error code for frontend mapping and localization");
    });

    it("should have correct metadata when accessing the metadata.", () => {
      const expectedMetadata = {
        description: "Machine-readable error code for frontend mapping and localization",
        example: "question-theme-referenced-by-live-questions",
      };

      expect(API_RESPONSE_EXCEPTION_DTO.shape.errorCode.meta()).toStrictEqual<Record<string, unknown>>(expectedMetadata);
    });
  });
});

