import { ZodError } from "zod";

import { ADMIN_QUESTION_THEME_DTO } from "@question-theme/contracts/dto/admin-question-theme/admin-question-theme.dto.shape";

import { HEX_COLOR_EXAMPLE } from "@shared/application/dto/zod/validators/string/constants/string.zod.validators.constants";

describe("Admin Question Theme DTO Shape", () => {
  let validAdminQuestionThemeDto: {
    id: string;
    slug: string;
    label: { en: string };
    aliases: { en: string[] };
    description: { en: string };
    color?: string;
    status: string;
    createdAt: string;
    updatedAt: string;
  };

  beforeEach(() => {
    validAdminQuestionThemeDto = {
      id: "60af924f4f1a2563f8e8b456",
      slug: "general-knowledge",
      label: { en: "General Knowledge" },
      aliases: { en: ["gk"] },
      description: { en: "A general knowledge theme" },
      color: "#FF5733",
      status: "active",
      createdAt: "2026-04-14T00:00:00.000Z",
      updatedAt: "2026-04-14T00:00:00.000Z",
    };
  });

  it("should pass validation when assigned valid values.", () => {
    expect(() => ADMIN_QUESTION_THEME_DTO.parse(validAdminQuestionThemeDto)).not.toThrow();
  });

  describe("id", () => {
    it("should throw a zod error when assigned a non-string value.", () => {
      const invalidDto = { ...validAdminQuestionThemeDto, id: 123 };

      expect(() => ADMIN_QUESTION_THEME_DTO.parse(invalidDto)).toThrow(ZodError);
    });

    it("should have correct description when accessing the description.", () => {
      expect(ADMIN_QUESTION_THEME_DTO.shape.id.description).toBe("Question Theme's unique identifier");
    });

    it("should have correct metadata when accessing the metadata.", () => {
      const expectedMetadata = {
        description: "Question Theme's unique identifier",
        example: "60af924f4f1a2563f8e8b456",
      };

      expect(ADMIN_QUESTION_THEME_DTO.shape.id.meta()).toStrictEqual<Record<string, unknown>>(expectedMetadata);
    });
  });

  describe("slug", () => {
    it("should throw a zod error when assigned a non-string value.", () => {
      const invalidDto = { ...validAdminQuestionThemeDto, slug: 123 };

      expect(() => ADMIN_QUESTION_THEME_DTO.parse(invalidDto)).toThrow(ZodError);
    });

    it("should have correct description when accessing the description.", () => {
      expect(ADMIN_QUESTION_THEME_DTO.shape.slug.description).toBe("Question Theme's unique slug in kebab-case");
    });

    it("should have correct metadata when accessing the metadata.", () => {
      const expectedMetadata = {
        description: "Question Theme's unique slug in kebab-case",
        example: "general-knowledge",
      };

      expect(ADMIN_QUESTION_THEME_DTO.shape.slug.meta()).toStrictEqual<Record<string, unknown>>(expectedMetadata);
    });
  });

  describe("label", () => {
    it("should throw a zod error when assigned a non localized text value.", () => {
      const invalidDto = { ...validAdminQuestionThemeDto, label: { en: 123 } };

      expect(() => ADMIN_QUESTION_THEME_DTO.parse(invalidDto)).toThrow(ZodError);
    });

    it("should have correct description when accessing the description.", () => {
      expect(ADMIN_QUESTION_THEME_DTO.shape.label.description).toBe("Question Theme's label");
    });
  });

