import { ZodError } from "zod";

import { QUESTION_THEME_ASSIGNMENT_MODIFICATION_DTO } from "@question/application/dto/question-theme-assignment-modification/question-theme-assignment-modification.dto.shape";

describe("Question Theme Assignment Modification DTO Shape", () => {
  let validDto: {
    isPrimary?: boolean;
    isHint?: boolean;
  };

  beforeEach(() => {
    validDto = {
      isPrimary: true,
      isHint: true,
    };
  });

  it("should pass validation when a valid QuestionThemeAssignmentModificationDto is provided.", () => {
    expect(() => QUESTION_THEME_ASSIGNMENT_MODIFICATION_DTO.parse(validDto)).not.toThrow();
  });

  it("should pass validation when only isPrimary is provided.", () => {
    const dto = { ...validDto, isHint: undefined };

    expect(() => QUESTION_THEME_ASSIGNMENT_MODIFICATION_DTO.parse(dto)).not.toThrow();
  });

  it("should pass validation when only isHint is provided.", () => {
    const dto = { ...validDto, isPrimary: undefined };

    expect(() => QUESTION_THEME_ASSIGNMENT_MODIFICATION_DTO.parse(dto)).not.toThrow();
  });

  it("should pass validation when an empty object is provided.", () => {
    expect(() => QUESTION_THEME_ASSIGNMENT_MODIFICATION_DTO.parse({})).not.toThrow();
  });

  describe("isPrimary", () => {
    it("should throw zod error when isPrimary is false.", () => {
      const invalid = { ...validDto, isPrimary: false };

      expect(() => QUESTION_THEME_ASSIGNMENT_MODIFICATION_DTO.parse(invalid)).toThrow(ZodError);
    });

    it("should throw zod error when isPrimary is not a boolean.", () => {
      const invalid = { ...validDto, isPrimary: "not-boolean" };

      expect(() => QUESTION_THEME_ASSIGNMENT_MODIFICATION_DTO.parse(invalid)).toThrow(ZodError);
    });

    it("should have correct metadata when accessing the metadata.", () => {
      const metadata = QUESTION_THEME_ASSIGNMENT_MODIFICATION_DTO.shape.isPrimary.unwrap().meta();
      const expectedMetadata = {
        description: "Set this theme as the primary theme for the question. Only true is accepted. The current primary will be automatically demoted",
      };

      expect(metadata).toStrictEqual<Record<string, unknown>>(expectedMetadata);
    });
  });

  describe("isHint", () => {
    it("should throw zod error when isHint is not a boolean.", () => {
      const invalid = { ...validDto, isHint: "not-boolean" };

      expect(() => QUESTION_THEME_ASSIGNMENT_MODIFICATION_DTO.parse(invalid)).toThrow(ZodError);
    });

    it("should have correct metadata when accessing the metadata.", () => {
      const metadata = QUESTION_THEME_ASSIGNMENT_MODIFICATION_DTO.shape.isHint.unwrap().meta();
      const expectedMetadata = {
        description: "Indicates if the assigned theme is a hint for the question's answer",
      };

      expect(metadata).toStrictEqual<Record<string, unknown>>(expectedMetadata);
    });
  });
});

import { ZodError } from "zod";

import { QUESTION_THEME_ASSIGNMENT_DTO } from "@question/application/dto/question/question-theme-assignment/question-theme-assignment.dto.shape";

describe("Question Theme Assignment DTO Shape", () => {
  let validQuestionThemeAssignmentDto: {
    theme: Record<string, unknown>;
    isPrimary: boolean;
    isHint: boolean;
  };

  beforeEach(() => {
    validQuestionThemeAssignmentDto = {
      theme: {
        id: "60af924f4f1a2563f8e8b456",
        slug: "general-knowledge",
        label: "General Knowledge",
        aliases: ["gk"],
        description: "General knowledge",
        status: "active",
        createdAt: "2026-04-14T00:00:00.000Z",
        updatedAt: "2026-04-14T00:00:00.000Z",
      },
      isPrimary: true,
      isHint: false,
    };
  });

  it("should pass validation when a valid QuestionThemeAssignmentDto is provided.", () => {
    expect(() => QUESTION_THEME_ASSIGNMENT_DTO.parse(validQuestionThemeAssignmentDto)).not.toThrow();
  });

  it("should have correct metadata when accessing the metadata.", () => {
    const expectedMetadata = {
      description: "Question's theme assignment",
    };

    expect(QUESTION_THEME_ASSIGNMENT_DTO.meta()).toStrictEqual<Record<string, unknown>>(expectedMetadata);
  });

  describe("theme", () => {
    it("should throw zod error when theme is invalid.", () => {
      const dtoWithInvalidTheme = { ...validQuestionThemeAssignmentDto, theme: "invalid" };

      expect(() => QUESTION_THEME_ASSIGNMENT_DTO.parse(dtoWithInvalidTheme)).toThrow(ZodError);
    });

    it("should have correct metadata when accessing the metadata.", () => {
      const metadata = QUESTION_THEME_ASSIGNMENT_DTO.shape.theme.meta();
      const expectedMetadata = {
        description: "Question assigned theme",
      };

      expect(metadata).toStrictEqual<Record<string, unknown>>(expectedMetadata);
    });
  });

  describe("isPrimary", () => {
    it("should throw a zod error when assigned a non-boolean value.", () => {
      const dtoWithInvalidIsPrimary = { ...validQuestionThemeAssignmentDto, isPrimary: "invalid" };

      expect(() => QUESTION_THEME_ASSIGNMENT_DTO.parse(dtoWithInvalidIsPrimary)).toThrow(ZodError);
    });

    it("should have correct metadata when accessing the metadata.", () => {
      const metadata = QUESTION_THEME_ASSIGNMENT_DTO.shape.isPrimary.meta();
      const expectedMetadata = {
        description: "Indicates if the assigned theme is the primary theme for the question",
      };

      expect(metadata).toStrictEqual<Record<string, unknown>>(expectedMetadata);
    });
  });

  describe("isHint", () => {
    it("should throw a zod error when assigned a non-boolean value.", () => {
      const dtoWithInvalidIsHint = { ...validQuestionThemeAssignmentDto, isHint: "invalid" };

      expect(() => QUESTION_THEME_ASSIGNMENT_DTO.parse(dtoWithInvalidIsHint)).toThrow(ZodError);
    });

    it("should have correct metadata when accessing the metadata.", () => {
      const metadata = QUESTION_THEME_ASSIGNMENT_DTO.shape.isHint.meta();
      const expectedMetadata = {
        description: "Indicates if the assigned theme is a hint for the question's answer",
      };

      expect(metadata).toStrictEqual<Record<string, unknown>>(expectedMetadata);
    });
